import React, { ReactElement } from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { DotMenuIcon } from '@dynatrace/strato-icons';

import { Button } from '../../../../../../buttons/button/Button.js';
import { WithChildren } from '../../../../../../core/types/with-children.js';
import { Menu } from '../../../../../../navigation/menu/Menu.js';
import { Group } from '../../../series-action/components/Group.js';
import { Item } from '../../../series-action/components/Item.js';
import { ItemIcon } from '../../../series-action/components/ItemIcon.js';
import { ItemTooltip } from '../../../series-action/components/ItemTooltip.js';
import { Label } from '../../../series-action/components/Label.js';

export interface LegendSeriesActionsProps extends WithChildren {
  onFocus: () => void;
  /** Disables the menu trigger. */
  disabled?: boolean;
  /** Makes the actions button visible or hidden **/
  visible?: boolean;
  onOpenChange?: (open: boolean) => void;
  isOpen: boolean;
  onBlur: () => void;
}

const StyledButton = /* @__PURE__ */ styled(Button)<{ visible: boolean }>(
  ({ visible }) => ({
    visibility: visible ? 'visible' : 'hidden',
    paddingTop: Spacings.Size4,
    paddingBottom: Spacings.Size4,
    paddingLeft: Spacings.Size6,
    paddingRight: Spacings.Size6,
  }),
);

/**
 * Wraps the passed child element in the corresponding Menu component
 * or calls the function recursively if the child is a Group
 *
 * @param child - element to render
 */
function renderActionChildren(child: ReactElement): ReactElement | undefined {
  if (!child) {
    return;
  }
  switch (child.type) {
    case Item:
      return (
        <Menu.Item
          onSelect={child.props.onSelect}
          disabled={child.props.disabled}
        >
          {React.Children.map(
            child?.props?.children,
            (itemChild: ReactElement) => {
              if (itemChild?.type === ItemTooltip) {
                return <Menu.ItemTooltip>{itemChild}</Menu.ItemTooltip>;
              } else if (itemChild?.type === ItemIcon) {
                return <Menu.ItemIcon>{itemChild}</Menu.ItemIcon>;
              }

              return itemChild;
            },
          )}
        </Menu.Item>
      );
    case Label:
      return <Menu.Label>{child}</Menu.Label>;
    case Group:
      return (
        <Menu.Group>
          {React.Children.map(
            child?.props?.children,
            (itemChild: ReactElement) => renderActionChildren(itemChild),
          )}
        </Menu.Group>
      );
    default:
      return;
  }
}

/**
 * LegendSeriesActions component.
 */
export const ChartLegendSeriesActions = (props: LegendSeriesActionsProps) => {
  const {
    children,
    disabled,
    onOpenChange,
    isOpen,
    visible = false,
    onFocus,
    onBlur,
  } = props;

  const handleFocus = (event: React.FocusEvent) => {
    event.stopPropagation();
    onFocus();
  };

  return (
    <Menu onOpenChange={onOpenChange}>
      <Menu.Trigger>
        <StyledButton
          data-testid="legend-more-actions-button"
          variant="default"
          disabled={disabled}
          visible={visible}
          onFocus={handleFocus}
          onBlur={onBlur}
        >
          <Button.Prefix>{<DotMenuIcon size="small" />}</Button.Prefix>
        </StyledButton>
      </Menu.Trigger>
      {!disabled && isOpen && (
        <Menu.Content>
          {React.Children.map(children as ReactElement, (child: ReactElement) =>
            renderActionChildren(child),
          )}
        </Menu.Content>
      )}
    </Menu>
  );
};

ChartLegendSeriesActions['displayName'] = 'LegendSeriesActions';
